    def emit(tag,value):
     print(json.dumps({'stage':tag,**value},ensure_ascii=False),flush=True)
    def blob(path):
     data=path.read_bytes()
     return hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()

    def sync_directory(path):
     fd=os.open(path,os.O_RDONLY)
     try: os.fsync(fd)
     finally: os.close(fd)
    def exact_file(path,body):
     path.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
     if path.exists() or path.is_symlink():
      if path.is_symlink() or not path.is_file() or path.read_bytes()!=body:
       raise RuntimeError('Retained source input differs: '+str(path))
      return
     fd,temporary=tempfile.mkstemp(prefix='.'+path.name+'-',dir=str(path.parent))
     try:
      with os.fdopen(fd,'wb') as stream:
       os.fchmod(stream.fileno(),0o600);stream.write(body);stream.flush();os.fsync(stream.fileno())
      try: os.link(temporary,path)
      except FileExistsError:
       if path.is_symlink() or not path.is_file() or path.read_bytes()!=body:
        raise RuntimeError('Retained source input differs: '+str(path))
      sync_directory(path.parent)
     finally:
      if os.path.exists(temporary): os.unlink(temporary)
    def restore_completed_archive(path,expected_sha256):
     if not isinstance(expected_sha256,str) or len(expected_sha256)!=64 or any(c not in '0123456789abcdef' for c in expected_sha256):
      raise RuntimeError('Select the exact retained result SHA256')
     if path.is_symlink() or not path.is_file() or path.stat().st_size>64*1024*1024:
      raise RuntimeError('Original completed-result archive identity differs')
     body=path.read_bytes()
     if hashlib.sha256(body).hexdigest()!=expected_sha256:
      raise RuntimeError('Original completed-result archive hash differs')
     with zipfile.ZipFile(io.BytesIO(body)) as archive:
      names=archive.namelist()
      if len(names)!=len(set(names)) or 'MANIFEST.json' not in names:
       raise RuntimeError('Original result archive has duplicate or missing members')
      manifest=json.loads(archive.read('MANIFEST.json'))
      if (manifest.get('schema')!='stellar-forge.stac-node-receiving-delivery.v1'
          or manifest.get('sourceMerge')!='cfd773e8636464df57b42d0d25ceb8d7618fafb8'
          or manifest.get('driverBlob') not in ('695a0634e16cf945c3d02449f1973274a541a3da','95a6d6d3a9b6e0ddc15bcb0370f4104ccf7ecf19','29a7a8587500d1dfd4881b77ac2c0c42ff84299e')
          or manifest.get('originalOperation')!=business
          or not isinstance(manifest.get('linkedOperation'),str)
          or not manifest['linkedOperation'].startswith(business+'-')
          or manifest.get('status')!='INTERRUPTED'):
       raise RuntimeError('Original transport-failure source or operation binding differs')
      entries=manifest.get('files')
      if not isinstance(entries,list) or len(entries)>2048:
       raise RuntimeError('Original result manifest is malformed')
      declared={}
      native_bodies={}
      receiving_bodies={}
      total=0
      for row in entries:
       name=row.get('path') if isinstance(row,dict) else None
       if not isinstance(name,str): raise RuntimeError('Original member path is missing')
       relative=pathlib.PurePosixPath(name)
       if relative.is_absolute() or str(relative)!=name or '..' in relative.parts or '\\' in name or name in declared:
        raise RuntimeError('Original member path is unsafe or duplicated')
       length=row.get('bytes')
       if type(length) is not int or length<0 or length>4*1024*1024:
        raise RuntimeError('Original result member length differs')
       total+=length
       if total>64*1024*1024: raise RuntimeError('Original result archive exceeds its retained size bound')
       info=archive.getinfo(name)
       mode=(info.external_attr>>16)&0o170000
       if info.is_dir() or mode not in (0,0o100000) or info.file_size!=length:
        raise RuntimeError('Original result member is not an exact regular file')
       raw=archive.read(name)
       if len(raw)!=length or hashlib.sha256(raw).hexdigest()!=row.get('sha256'):
        raise RuntimeError('Original result member bytes differ: '+name)
       declared[name]=row
       if name.startswith('receiving/'):
        receiving_bodies[name[len('receiving/'):]]=raw
       if name.startswith('workspace/'):
        relative_name=name[len('workspace/'):]
        if not relative_name.startswith(('customer/','receiving/')): raise RuntimeError('Original workspace member is not selected')
        receiving_bodies[relative_name]=raw
       if name.startswith('native-record/'):
        child=pathlib.PurePosixPath(name[len('native-record/'):])
        if str(child) in ('','.'): raise RuntimeError('Original native record member is missing')
        native_bodies[str(child)]=raw
      if set(names)!=set(declared)|{'MANIFEST.json'}:
       raise RuntimeError('Original result member set differs')
      progress=json.loads(archive.read('receiving/progress.json'))
      if not isinstance(progress.get('stages'),list) or progress.get('status')!='INTERRUPTED' or not isinstance(progress.get('error'),dict):
       raise RuntimeError('Select the original ended receiving outcome')
      if progress.get('stages') and not any(name.startswith(('customer/','receiving/')) for name in receiving_bodies):
       raise RuntimeError('The original completed stages require their retained workspaces')
      restored_receiving.update(receiving_bodies)
      if not {'request.json','state.json','result.json'}.issubset(native_bodies):
       raise RuntimeError('Original complete native request/result is missing')
      request=json.loads(native_bodies['request.json'])
      if request['intent']['operation_id']!=manifest['linkedOperation']:
       raise RuntimeError('Original result and native request operations differ')
      record_key=hashlib.sha256(request['intent']['operation_id'].encode('utf-8')).hexdigest()
      restored=pathlib.Path('/dev/c79f-stac-receiving-placement')/('native-placement-'+record_key[:24])/'work/records'/record_key
      if manifest.get('nativeRecord')!=str(restored):
       raise RuntimeError('Original native record path identity differs')
      records=restored.parent
      records.mkdir(parents=True,exist_ok=True,mode=0o700)
      if native.run_path(request['intent']['operation_id'],str(records))!=restored:
       raise RuntimeError('Original native record directory identity differs')
      if restored.exists() or restored.is_symlink():
       if restored.is_symlink() or not restored.is_dir():
        raise RuntimeError('Original retained native record path changed')
       for name,raw in native_bodies.items():
        exact_file(restored/name,raw)
      else:
       staging=pathlib.Path(tempfile.mkdtemp(prefix='.original-'+restored.name[:12]+'-',dir=str(records)))
       try:
        for name,raw in native_bodies.items(): exact_file(staging/name,raw)
        sync_directory(staging)
        try: os.rename(staging,restored)
        except OSError as error:
         if error.errno not in (errno.EEXIST,errno.ENOTEMPTY): raise
         if restored.is_symlink() or not restored.is_dir(): raise
         for name,raw in native_bodies.items(): exact_file(restored/name,raw)
        sync_directory(records)
       finally:
        if staging.exists(): shutil.rmtree(staging)
      emit('original-result-restored',{'archive':str(path),'archive_sha256':expected_sha256,'record':str(restored),'native_operation':request['intent']['operation_id'],'members':len(native_bodies),'original_request_sha256':hashlib.sha256(native_bodies['request.json']).hexdigest(),'original_result_sha256':hashlib.sha256(native_bodies['result.json']).hexdigest()})
      return restored
    if blob(host/'native_placement.py')!='d90ec7fa6e270fd718a3ee676388847540306eb3':
     raise RuntimeError('Original maintained placement source changed; inspect its current contract')
