    expected={'stac-workspace-client.mjs':'450cb573b730fa7ea4b3d1922217b55adf32c246','stac-workspace.mjs':'229a1f33cecba23b7e8851b89436fcaa0a481900','stac-workspace-cli.mjs':'8713553b3c268952b07c06a5a996fddc91bd383e','catalog/stac-workspace.mjs':'8aa1835de6c34e37ccf37f9dd7a549a3fc5c8c34'}
    for name,wanted in expected.items():
     path=repo/'stellar-forge/mcp-merchant-operator'/name
     if blob(path)!=wanted:
      current=path.read_bytes();normalized=current.rstrip(b'\n')+b'\n'
      digest=hashlib.sha1(b'blob '+str(len(normalized)).encode()+b'\0'+normalized).hexdigest()
      if digest!=wanted or path.is_symlink():
       raise RuntimeError('Frozen merged product leaf changed: '+name)
      fd,temporary=tempfile.mkstemp(prefix='.'+path.name+'-',dir=str(path.parent))
